CREATE OR REPLACE FUNCTION public.get_credit_wallet() RETURNS TABLE (user_id uuid, balance integer, lifetime_earned integer, lifetime_spent integer, vip_tier text, vip_until timestamp with time zone, last_ad_reward_at timestamp with time zone) LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, auth AS $$ DECLARE v_user_id uuid := auth.uid(); BEGIN IF v_user_id IS NULL THEN RAISE EXCEPTION 'Usuário não autenticado'; END IF; INSERT INTO public.credit_wallets (user_id) VALUES (v_user_id) ON CONFLICT (user_id) DO NOTHING; RETURN QUERY SELECT cw.user_id, cw.balance, cw.lifetime_earned, cw.lifetime_spent, cw.vip_tier, cw.vip_until, cw.last_ad_reward_at FROM public.credit_wallets AS cw WHERE cw.user_id = v_user_id; END; $$;